const update = $input.first().json;
const user = update.message?.from ?? update.callback_query?.from;
const chat = update.message?.chat ?? update.callback_query?.message?.chat;
if (!user?.id || !chat?.id || user.is_bot || chat.type !== 'private' || String(user.id) !== String(chat.id)) {
  throw new Error('Only direct messages from a human user are supported.');
}
return [{ json: {
  user_id: String(user.id), chat_id: String(chat.id),
  username: user.username || '', name: user.first_name || '',
  action: String(update.callback_query?.data ?? update.message?.text ?? '').trim(),
  callback_query_id: update.callback_query?.id || '',
}, pairedItem: { item: 0 } }];

const session = $input.first().json;
const source = $('Normalize Request').first().json;
const config = $('Project Configuration').first().json.config;
const text = String(source.action || '').trim();
if (!['template_a', 'template_b'].includes(session.template_key)) throw new Error('Select a template first.');
const lines = text.split(/\r?\n/).map(line => line.trim()).filter(Boolean);
const emailLine = lines.pop() || '';
const emailMatch = emailLine.match(/^Email:\s*([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})$/i);
if (!emailMatch || emailMatch[1].length > 254) throw new Error('End the message with one valid Email line.');
if (!lines.length || lines.length % 2 !== 0 || lines.length > 40) throw new Error('Provide between 1 and 20 two-line records.');
const seen = new Set();
const records = [];
for (let i = 0; i < lines.length; i += 2) {
  // Links are embedded in PDFs; they are never fetched by this workflow.
  const link = lines[i].match(/^Link:\s*(https:\/\/([a-z0-9.-]+)(?:\/[^\s<>"'`\\]*)?)$/i);
  const fields = lines[i + 1].match(/^Record:\s*([A-Z0-9][A-Z0-9_-]{0,63})\s*\|\s*Department:\s*([^|\r\n]{1,80})\s*\|\s*Reference:\s*([A-Z0-9][A-Z0-9_-]{0,63})$/i);
  if (!link || link[1].length > 2048 || !config.allowedLinkHosts.map(host => host.toLowerCase()).includes(link[2].toLowerCase()) || !fields) {
    throw new Error('Invalid record format or link host.');
  }
  const [, record_id, department, reference] = fields;
  if (!department.trim() || /[<>\x00-\x1f]/.test(department) || seen.has(record_id.toLowerCase())) throw new Error('Invalid department or duplicate record ID.');
  seen.add(record_id.toLowerCase());
  const fileName = `${record_id} - ${reference}`;
  records.push({ json: { template_key: session.template_key, url: link[1], record_id, department: department.trim(), reference,
    email: emailMatch[1], fileName, pdfName: `${fileName}.pdf`, chat_id: source.chat_id }, pairedItem: { item: 0 } });
}
return records;

return $input.all().map((item, index) => {
  const doc = item.json;
  const expected = $('Validate Document Batch').itemMatching(index).json;
  const runs = [];
  function collect(blocks) {
    for (const block of blocks || []) {
      for (const el of block.paragraph?.elements || []) {
        if (el.textRun?.content && Number.isInteger(el.startIndex)) runs.push({ start: el.startIndex, text: el.textRun.content });
      }
      for (const row of block.table?.tableRows || []) for (const cell of row.tableCells || []) collect(cell.content);
    }
  }
  collect(doc.body?.content);
  let text = ''; const positions = [];
  for (const run of runs) for (let i = 0; i < run.text.length; i++) { text += run.text[i]; positions.push(run.start + i); }
  function findRange(value) {
    const start = text.indexOf(value);
    if (start < 0 || text.indexOf(value, start + 1) >= 0) throw new Error('Template must contain the contact email and Open record label exactly once.');
    const end = start + value.length - 1;
    for (let i = start; i < end; i++) if (positions[i + 1] !== positions[i] + 1) throw new Error('Link text spans separate document elements.');
    return { startIndex: positions[start], endIndex: positions[end] + 1 };
  }
  return { json: { documentId: doc.documentId, title: doc.title, email: expected.email,
    emailRange: findRange(expected.email), recordRange: findRange('Open record') }, pairedItem: { item: index } };
});

