// Replace these placeholders only in your private n8n instance.
const config = {
  ownerUserId: 'REPLACE_WITH_OWNER_USER_ID',
  accessTableId: 'REPLACE_WITH_ACCESS_TABLE_ID',
  sessionTableId: 'REPLACE_WITH_SESSION_TABLE_ID',
  templateAId: 'REPLACE_WITH_TEMPLATE_A_DOCUMENT_ID',
  templateBId: 'REPLACE_WITH_TEMPLATE_B_DOCUMENT_ID',
  allowedLinkHosts: ['example.com'],
};
if (Object.values(config).some(value => typeof value === 'string' && value.startsWith('REPLACE_WITH_'))) {
  throw new Error('Complete Project Configuration before enabling this workflow.');
}
if (!/^[1-9]\d+$/.test(config.ownerUserId) || !config.allowedLinkHosts.length) {
  throw new Error('Invalid owner ID or empty link host allowlist.');
}
return $input.all().map((item, index) => ({ json: { ...item.json, config }, pairedItem: { item: index } }));
